 void SetupExplorationCaptureF(){world.NewGame(0);world.WalletFunds=100000;world.EnsureProbeCatalog();encounterSelectionF=world.Exploration.Encounters.First(e=>e.Template=="outpost").Id;explorationTabF=captureScene switch{"stage-f-pocket"=>1,"stage-f-contacts"=>2,"stage-f-wormholes"=>3,"stage-f-filaments"=>4,_=>0};if(explorationTabF==1){world.Undock();world.EnterEncounterF("f:"+encounterSelectionF);}desktop.Clear();OpenExplorationF();}
 int checksUiF;
 void RunExplorationUiChecksF(int frame){void Check(bool ok,string name){if(!ok)throw new Exception("STAGE F UI FAIL / "+name);checksUiF++;Console.WriteLine("STAGE F UI PASS / "+name);}void Click(string tip)=>TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());switch(frame){
 case 0:Check(desktop.Any(w=>w.Kind==ViewMode.Exploration),"Exploration workspace opens");Check(ui.Hits.Any(h=>h.Tip=="Stage F warp"),"Resolved-site warp control reachable");Click("Stage F tab / Expeditions / contacts");break;
 case 1:Click("Stage F offer arc");Check(world.Exploration.Arcs.Count==1,"Offer button creates durable contact arc");break;
 case 2:Click("Stage F branch / Archive");Check(world.Exploration.Arcs.Single().Branch=="Archive","Branch choice creates objective encounter");Click("Stage F tab / Filaments / hazards");break;
 case 3:decimal funds=world.Balance;Click("Stage F buy filament");Check(world.Hangar.GetValueOrDefault("f_filament")==1&&world.Balance==funds-200,"Purchase charges wallet and creates finite stock item");break;
 case 4:Click("Stage F load filament");Check(world.CargoItems.GetValueOrDefault("f_filament")==1,"Cargo transfer uses real item");Click("Stage F weather / Gamma");Check(weatherF=="Gamma","Weather choice changes configuration");Click("Stage F tab / Wormholes");break;
 case 5:Check(ui.Hits.Any(h=>h.Tip.StartsWith("Stage F transit / ")),"Paired connection transit control reachable");world.Undock();world.EnterEncounterF("f:"+encounterSelectionF);Click("Stage F tab / Active pocket");break;
 case 6:Click("Stage F activate gate");Check(noticeF.Contains("locked"),"Gate button enforces live objective");Click("Stage F approach gate");Check(world.Player.OrderTarget.Contains(":gate:"),"Approach button issues real navigation order");Check(ui.Hits.Any(h=>h.Tip=="Stage F hacking"),"Hacking workspace reachable");Console.WriteLine(checksUiF+" Stage F UI checks passed.");break;}}
